// Package ini parses INI configuration text.
package ini

import (
	"fmt"
	"strings"
)

// File maps a section name to its keys and values. Keys before any header are in section "".
type File map[string]map[string]string

// Error is a syntax error at a 1-based line.
type Error struct {
	Line int
	Msg  string
}

func (e *Error) Error() string {
	return fmt.Sprintf("ini: line %d: %s", e.Line, e.Msg)
}

// Parse parses INI text.
func Parse(text string) (File, error) {
	file := File{}
	section := ""
	lines := strings.Split(text, "\n")
	for i := 0; i < len(lines); i++ {
		number := i + 1
		line := trim(lines[i])
		for strings.HasSuffix(line, `\`) {
			line = trim(strings.TrimSuffix(line, `\`))
			if i+1 < len(lines) {
				i++
				line += " " + trim(lines[i])
			}
		}
		fail := func(msg string) (File, error) { return nil, &Error{Line: number, Msg: msg} }
		switch {
		case line == "" || line[0] == ';' || line[0] == '#':
		case line[0] == '[':
			if !strings.HasSuffix(line, "]") {
				return fail("unclosed section header")
			}
			section = trim(line[1 : len(line)-1])
			if section == "" {
				return fail("empty section name")
			}
			if file[section] == nil {
				file[section] = map[string]string{}
			}
		default:
			key, value, ok := strings.Cut(line, "=")
			if !ok {
				return fail("missing =")
			}
			if key = trim(key); key == "" {
				return fail("empty key")
			}
			value, msg := unquote(trim(value))
			if msg != "" {
				return fail(msg)
			}
			if file[section] == nil {
				file[section] = map[string]string{}
			}
			file[section][key] = value
		}
	}
	return file, nil
}

func trim(s string) string {
	return strings.Trim(s, " \t\r")
}

// unquote decodes a value wrapped in double quotes, or returns any other value unchanged.
func unquote(v string) (string, string) {
	if !strings.HasPrefix(v, `"`) {
		return v, ""
	}
	var b strings.Builder
	for i := 1; i < len(v); i++ {
		switch v[i] {
		case '"':
			if i != len(v)-1 {
				return "", "text after closing quote"
			}
			return b.String(), ""
		case '\\':
			if i++; i == len(v) || v[i] != '"' && v[i] != '\\' {
				return "", "invalid escape"
			}
		}
		b.WriteByte(v[i])
	}
	return "", "unterminated quote"
}

