// Package ratelimit is a token-bucket rate limiter driven by an injected clock.
package ratelimit

import (
	"math"
	"time"
)

// Clock supplies the current time.
type Clock interface {
	Now() time.Time
}

// Limiter is a token bucket.
type Limiter struct {
	clock  Clock
	rate   float64
	burst  float64
	tokens float64
	last   time.Time
}

// New returns a limiter refilling rate tokens per second up to burst tokens.
func New(rate float64, burst int, clock Clock) *Limiter {
	size := float64(max(burst, 0))
	return &Limiter{clock: clock, rate: rate, burst: size, tokens: size, last: clock.Now()}
}

// refill adds the tokens earned since the last observation. A clock going back earns nothing.
func (l *Limiter) refill() {
	now := l.clock.Now()
	if !now.After(l.last) {
		return
	}
	if l.rate > 0 {
		l.tokens = min(l.burst, l.tokens+now.Sub(l.last).Seconds()*l.rate)
	}
	l.last = now
}

// Allow is AllowN(1).
func (l *Limiter) Allow() bool {
	return l.AllowN(1)
}

// AllowN takes n tokens if they are available.
func (l *Limiter) AllowN(n int) bool {
	l.refill()
	if n < 0 || float64(n) > l.tokens {
		return false
	}
	l.tokens -= float64(n)
	return true
}

// Tokens reports the available tokens.
func (l *Limiter) Tokens() float64 {
	l.refill()
	return l.tokens
}

// Delay reports how long until AllowN(n) can succeed.
func (l *Limiter) Delay(n int) time.Duration {
	l.refill()
	need := float64(n) - l.tokens
	switch {
	case n < 0 || float64(n) > l.burst:
		return -1
	case need <= 0:
		return 0
	case l.rate <= 0:
		return -1
	}
	return time.Duration(math.Ceil(need / l.rate * float64(time.Second)))
}

// SetRate changes the refill rate.
func (l *Limiter) SetRate(rate float64) {
	l.refill()
	l.rate = rate
}

// SetBurst changes the bucket size.
func (l *Limiter) SetBurst(burst int) {
	l.refill()
	l.burst = float64(max(burst, 0))
	l.tokens = min(l.tokens, l.burst)
}

